'use client';

import { QrCode as QrCodePrimitive, useQrCode, useQrCodeContext } from '@ark-ui/react/qr-code';
import { clsx } from 'clsx';
import type { ComponentProps, ComponentRef } from 'react';
import { forwardRef } from 'react';
import styles from './QrCode.module.css';

const QrCode = forwardRef<
  ComponentRef<typeof QrCodePrimitive.Root>,
  ComponentProps<typeof QrCodePrimitive.Root>
>(function QrCode({ className, ...props }, ref) {
  return (
    <QrCodePrimitive.Root
      ref={ref}
      className={clsx(styles.root, className)}
      {...props}
      data-slot="qr-code-root"
    />
  );
});

const QrCodeRootProvider = forwardRef<
  ComponentRef<typeof QrCodePrimitive.RootProvider>,
  ComponentProps<typeof QrCodePrimitive.RootProvider>
>(function QrCodeRootProvider({ className, ...props }, ref) {
  return (
    <QrCodePrimitive.RootProvider
      ref={ref}
      className={clsx(styles.root, className)}
      {...props}
      data-slot="qr-code-root-provider"
    />
  );
});

const QrCodeFrame = forwardRef<
  ComponentRef<typeof QrCodePrimitive.Frame>,
  ComponentProps<typeof QrCodePrimitive.Frame>
>(function QrCodeFrame({ className, ...props }, ref) {
  return (
    <QrCodePrimitive.Frame
      ref={ref}
      className={clsx(styles.frame, className)}
      {...props}
      data-slot="qr-code-frame"
    />
  );
});

const QrCodePattern = forwardRef<
  ComponentRef<typeof QrCodePrimitive.Pattern>,
  ComponentProps<typeof QrCodePrimitive.Pattern>
>(function QrCodePattern(props, ref) {
  return <QrCodePrimitive.Pattern ref={ref} {...props} data-slot="qr-code-pattern" />;
});

const QrCodeOverlay = forwardRef<
  ComponentRef<typeof QrCodePrimitive.Overlay>,
  ComponentProps<typeof QrCodePrimitive.Overlay>
>(function QrCodeOverlay({ className, ...props }, ref) {
  return (
    <QrCodePrimitive.Overlay
      ref={ref}
      className={clsx(styles.overlay, className)}
      {...props}
      data-slot="qr-code-overlay"
    />
  );
});

const QrCodeDownloadTrigger = forwardRef<
  ComponentRef<typeof QrCodePrimitive.DownloadTrigger>,
  ComponentProps<typeof QrCodePrimitive.DownloadTrigger>
>(function QrCodeDownloadTrigger({ className, ...props }, ref) {
  return (
    <QrCodePrimitive.DownloadTrigger
      ref={ref}
      className={clsx(styles.downloadTrigger, className)}
      {...props}
      data-slot="qr-code-download-trigger"
    />
  );
});

const QrCodeContext = QrCodePrimitive.Context;

export {
  QrCode,
  QrCodeContext,
  QrCodeDownloadTrigger,
  QrCodeFrame,
  QrCodeOverlay,
  QrCodePattern,
  QrCodeRootProvider,
  useQrCode,
  useQrCodeContext,
};
export type {
  QrCodeContextProps,
  QrCodeDownloadTriggerProps,
  QrCodeFrameProps,
  QrCodeGenerateOptions,
  QrCodeOverlayProps,
  QrCodePatternProps,
  QrCodeRootProps,
  QrCodeRootProviderProps,
  QrCodeValueChangeDetails,
  UseQrCodeContext,
  UseQrCodeProps,
  UseQrCodeReturn,
} from '@ark-ui/react/qr-code';

@layer moduix.components {
  .root {
    display: inline-grid;
    grid-template-columns: minmax(0, 1fr);
    justify-items: center;
    gap: var(--moduix-spacing-3);
    width: min(var(--moduix-qr-code-size, 8rem), 100%);
  }

  .frame {
    width: 100%;
    aspect-ratio: 1;
    fill: currentColor;
  }

  /* Ark centers the overlay on its containing block; the first grid cell keeps it on the frame,
     so percentages also resolve against the frame. */
  .overlay {
    grid-area: 1 / 1 / 2 / 2;
    box-sizing: border-box;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: calc(100% / 3);
    aspect-ratio: 1;
    padding: var(--moduix-spacing-1);
    border-radius: var(--moduix-radius-sm);
    background-color: var(--moduix-color-background);
    color: var(--moduix-color-foreground);

    & :where(img, svg) {
      width: 100%;
      height: 100%;
      object-fit: contain;
    }
  }

  .downloadTrigger {
    box-sizing: border-box;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--moduix-spacing-2);
    min-height: var(--moduix-size-md);
    padding-inline: var(--moduix-spacing-4);
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-radius-md);
    background-color: var(--moduix-color-background);
    color: var(--moduix-color-foreground);
    appearance: none;
    font: inherit;
    font-size: var(--moduix-text-sm);
    font-weight: var(--moduix-weight-medium);
    line-height: var(--moduix-line-height-text-sm);
    user-select: none;
    white-space: nowrap;
    cursor: pointer;
    transition:
      background-color var(--moduix-transition-default),
      opacity var(--moduix-transition-default);

    & :where(svg) {
      width: var(--moduix-spacing-4);
      height: var(--moduix-spacing-4);
      flex-shrink: 0;
    }

    @media (hover: hover) {
      &:hover:not(:disabled) {
        background-color: var(--moduix-color-accent);
      }
    }

    &:focus-visible {
      outline: var(--moduix-focus-ring-width) solid var(--moduix-color-ring);
      outline-offset: calc(var(--moduix-border-width-sm) * -1);
    }

    &:active:not(:disabled) {
      opacity: 0.94;
    }

    &:disabled {
      pointer-events: none;
      opacity: var(--moduix-opacity-disabled);
    }
  }
}
